import { useState } from "react";
import { NavLink, Outlet, Link } from "react-router-dom";

const NAV_ITEMS = [
  { id: "dashboard", label: "Dashboard", icon: "📊", href: "/student/dashboard" },
  { id: "search", label: "Find offers", icon: "🔍", href: "/student/search" },
  { id: "profile", label: "My profile", icon: "👤", href: "/student/profile" },
];

export default function StudentLayout() {
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <div className="flex h-screen overflow-hidden bg-[#F8FAFC]">
      {/* Sidebar Desktop */}
      <aside className="hidden md:flex flex-col w-64 bg-white border-r border-slate-200 shrink-0">
        <div className="p-6">
          <Link to="/" className="text-2xl font-black text-slate-900 tracking-tight">
            Stag<span className="text-blue-600">.</span>io
          </Link>
          <div className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">Student Portal</div>
        </div>
        
        <nav className="flex-1 px-4 space-y-2 mt-4">
          {NAV_ITEMS.map((item) => (
            <NavLink
              key={item.id}
              to={item.href}
              className={({ isActive }) => 
               ` flex items-center gap-3 px-4 py-3 rounded-2xl text-sm font-bold transition-all ${
                  isActive ? "bg-blue-50 text-blue-600 shadow-sm" : "text-slate-500 hover:bg-slate-50"
                }
              `}
            >
              <span className="text-lg">{item.icon}</span>
              {item.label}
            </NavLink>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-2xl">
            <div className="w-9 h-9 rounded-xl bg-blue-600 flex items-center justify-center text-white font-bold text-xs">AB</div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-bold text-slate-900 truncate">Amira Benali</p>
              <p className="text-[10px] text-slate-400">L3 Informatique</p>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden flex items-center justify-between p-4 bg-white border-b border-slate-100 shrink-0">
          <button onClick={() => setMobileOpen(true)} className="p-2 text-slate-600 text-xl">☰</button>
          <span className="font-bold tracking-tight">Stag.io</span>
          <div className="w-8 h-8 rounded-lg bg-blue-600"></div>
        </header>

        <main className="flex-1 overflow-y-auto p-5 md:p-10">
          {/* هنا تظهر الصفحات (Dashboard, Search, Profile) */}
          <Outlet /> 
        </main>
      </div>

      {/* Mobile Sidebar Overlay */}
      {mobileOpen && (
        <div className="fixed inset-0 z-50 bg-slate-900/20 backdrop-blur-sm md:hidden" onClick={() => setMobileOpen(false)}>
          <div className="w-64 h-full bg-white shadow-xl animate-in slide-in-from-left duration-300" onClick={e => e.stopPropagation()}>
             {/* يمكنك تكرار محتوى السايدبار هنا أو استدعاء مكون Sidebar منفصل */}
             <div className="p-6 font-bold border-b">Menu</div>
             <div className="p-4 space-y-4">
                {NAV_ITEMS.map(item => (
                  <Link key={item.id} to={item.href} onClick={() => setMobileOpen(false)} className="block p-2 font-bold text-slate-600">
                    {item.icon} {item.label}
                  </Link>
                ))}
             </div>
          </div>
        </div>
      )}
    </div>
  );
}
